"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";

export function OrbitPrimitive({ center, orbiting }: { center: ReactNode; orbiting: ReactNode }) {
  const reduceMotion = useReducedMotion();
  return (
    <div style={{ position: "relative", display: "grid", placeItems: "center", width: 112, height: 112 }}>
      {center}
      <motion.div
        animate={{ rotate: reduceMotion ? 0 : 360 }}
        transition={{ duration: 6, ease: "linear", repeat: reduceMotion ? 0 : Infinity }}
        style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center" }}
      >
        <span style={{ transform: "translateX(56px)" }}>{orbiting}</span>
      </motion.div>
    </div>
  );
}
